diff --git a/mail/base/test/browser/browser_folderTreeProperties.js b/mail/base/test/browser/browser_folderTreeProperties.js
index b6795e1ae11..27855da9e16 100644
--- a/mail/base/test/browser/browser_folderTreeProperties.js
+++ b/mail/base/test/browser/browser_folderTreeProperties.js
@@ -41,6 +41,11 @@ add_setup(async function () {
   await SpecialPowers.pushPrefEnv({
     set: [["ui.prefersReducedMotion", 1]],
   });
+  // Temporarily disable the new HTML color picker for this test.
+  // See bug 2007435 for adapting the tests to the new picker behavior.
+  await SpecialPowers.pushPrefEnv({
+    set: [["dom.forms.html_color_picker.enabled", false]],
+  });
   FolderTreeProperties.resetColors();

   const account = MailServices.accounts.createAccount();
